<?php declare(strict_types=1);
function annualJournalDatabase(PDO $db):array{
 $c=Kulturhus\Native\TestSupport::config();if(($c['owner']??'')!=='isolated-native-ci'||($c['label']??'')!=='native-balance-annual-journal-interface'||($c['host']??'')!=='127.0.0.1'||($c['port']??0)!==13371||!preg_match('/\Akh_native_[a-f0-9]{24}\z/D',$c['database']??'')||$db->query('SELECT DATABASE()')->fetchColumn()!==$c['database']||(int)$db->query('SELECT MAX(version)FROM schema_migrations')->fetchColumn()!==135)throw new RuntimeException('Exact own annual source database required');return$c;
}
function annualJournalClubs(array $f):array{$clubs=array_values($f['data']['profile_clubs']);if(count($clubs)!==8||$f['data']['year']!==2025)throw new RuntimeException('Eight actual annual source clubs required');foreach($clubs as$i=>$club)if($club!=='annual-journal-ui-'.($i+1))throw new RuntimeException('Exact annual source club required');return$clubs;}
function annualJournalFilter(array $f):callable{
 $clubs=annualJournalClubs($f);$marks=implode(',',array_fill(0,8,'?'));return static fn(string$table):array=>match($table){'balance_years','balance_entries'=>[' WHERE club_id NOT IN('.$marks.') OR tax_year<>?',[...$clubs,2025]],'audit_events'=>[' WHERE sequence<=?',[$f['data']['proof_baseline']['audit']]],default=>['',[]]};
}
function annualJournalRows(PDO $db,string $table,array $f):array{
 if(!in_array($table,['balance_years','balance_entries','audit_events'],true))throw new RuntimeException('Exact annual source table required');$q=$db->prepare('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE()AND TABLE_NAME=? ORDER BY ORDINAL_POSITION');$q->execute([$table]);$cols=$q->fetchAll(PDO::FETCH_COLUMN);$q=$db->prepare("SELECT COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE()AND TABLE_NAME=? AND CONSTRAINT_NAME='PRIMARY' ORDER BY ORDINAL_POSITION");$q->execute([$table]);$pk=$q->fetchAll(PDO::FETCH_COLUMN);if(!$cols||!$pk)throw new RuntimeException('Actual annual columns and primary keys required');$clubs=annualJournalClubs($f);$marks=implode(',',array_fill(0,8,'?'));[$where,$args]=match($table){'audit_events'=>['sequence>?',[$f['data']['proof_baseline']['audit']]],'balance_source_history'=>['club_id IN('.$marks.')',$clubs],default=>['club_id IN('.$marks.') AND tax_year=?',[...$clubs,2025]]};$quote=static fn(string$v):string=>'`'.str_replace('`','``',$v).'`';$q=$db->prepare('SELECT '.implode(',',array_map($quote,$cols)).' FROM '.$quote($table).' WHERE '.$where.' ORDER BY '.implode(',',array_map($quote,$pk)));$q->execute($args);return$q->fetchAll(PDO::FETCH_ASSOC);
}
function annualJournalSnapshot(PDO $db,array $f,int $profile):array{
 annualJournalDatabase($db);$tables=array_values(array_diff($db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN),['native_auth_sessions','native_auth_limits','native_language_preferences']));$out=['protected_sha256'=>ownOriginalDatabaseHash($db,$tables,annualJournalFilter($f)),'protected_tables'=>count($tables),'profile'=>$profile];foreach(['balance_years'=>'years','balance_entries'=>'entries','audit_events'=>'audits']as$table=>$key)$out[$key]=annualJournalRows($db,$table,$f);$ledger=new Kulturhus\Verein\BalanceLedger($db,'annualjournal-'.$profile.'-finance');$out['state']=$ledger->report(2025);return$out;
}
function annualJournalProof(array $f):void{
 $profile=$_SERVER['HTTP_X_OWNED_SOURCE_OUTCOME']??null;if(PHP_SAPI!=='cli-server'||($_SERVER['REQUEST_METHOD']??'')!=='GET'||!is_string($profile)||!preg_match('/\A[1-8]\z/D',$profile)||!is_string($_SERVER['HTTP_X_OWNED_ANNUAL_JOURNAL_PROOF']??null)||!hash_equals($f['data']['proof_nonce']??'',$_SERVER['HTTP_X_OWNED_ANNUAL_JOURNAL_PROOF'])){http_response_code(403);exit;}require_once dirname(__DIR__,2).'/src/bootstrap.php';require_once __DIR__.'/original-database-hash.php';$db=Kulturhus\Native\TestSupport::db();header('Content-Type: application/json; charset=UTF-8');header('Cache-Control: no-store');echo json_encode(annualJournalSnapshot($db,$f,(int)$profile),JSON_THROW_ON_ERROR),PHP_EOL;
}
